class Solution {
public:
    int numWays(int steps, int arrLen) {
        long long MOD = 1e9 + 7;
        int maxPos = std::min(steps / 2, arrLen - 1);
        std::vector<long long> dp(maxPos + 1, 0);
        dp[0] = 1;

        for (int step = 0; step < steps; ++step) {
            std::vector<long long> nxt(maxPos + 1, 0);
            for (int j = 0; j <= maxPos; ++j) {
                nxt[j] = dp[j];
                if (j > 0) nxt[j] = (nxt[j] + dp[j - 1]) % MOD;
                if (j < maxPos) nxt[j] = (nxt[j] + dp[j + 1]) % MOD;
            }
            dp = std::move(nxt);
        }
        return dp[0];
    }
};

class Solution {
    public int numWays(int steps, int arrLen) {
        long MOD = 1_000_000_007L;
        int maxPos = Math.min(steps / 2, arrLen - 1);
        long[] dp = new long[maxPos + 1];
        dp[0] = 1;

        for (int step = 0; step < steps; step++) {
            long[] nxt = new long[maxPos + 1];
            for (int j = 0; j <= maxPos; j++) {
                nxt[j] = dp[j];
                if (j > 0) nxt[j] = (nxt[j] + dp[j - 1]) % MOD;
                if (j < maxPos) nxt[j] = (nxt[j] + dp[j + 1]) % MOD;
            }
            dp = nxt;
        }
        return (int) dp[0];
    }
}

var numWays = function(steps, arrLen) {
    const MOD = 1000000007n;
    const maxPos = Math.min(Math.floor(steps / 2), arrLen - 1);
    let dp = new Array(maxPos + 1).fill(0n);
    dp[0] = 1n;

    for (let step = 0; step < steps; step++) {
        const nxt = new Array(maxPos + 1).fill(0n);
        for (let j = 0; j <= maxPos; j++) {
            nxt[j] = dp[j];
            if (j > 0) nxt[j] = (nxt[j] + dp[j - 1]) % MOD;
            if (j < maxPos) nxt[j] = (nxt[j] + dp[j + 1]) % MOD;
        }
        dp = nxt;
    }
    return Number(dp[0]);
};
